import {blank,uid,currentMonth,addMonth,today,dateAt} from './core.mjs';
// Synthetic, ephemeral examples. No records copied from the user's Notion.
export function demo(){const s=blank(),m=currentMonth(),a=uid(),b=uid(),c=uid();s.accounts=[{id:a,name:'Conta principal',kind:'checking',opening:250000,openingDate:addMonth(m,-6)+'-01',color:'#147d64'},{id:b,name:'Reserva de emergência',kind:'saving',opening:1250000,openingDate:addMonth(m,-6)+'-01',color:'#8b6bc2'},{id:c,name:'Carteira',kind:'cash',opening:18000,openingDate:addMonth(m,-6)+'-01',color:'#ba873c'}];const category=name=>s.categories.find(c=>c.name===name).id;for(let i=5;i>=0;i--){const mon=addMonth(m,-i);s.transactions.push({id:uid(),description:'Salário · exemplo',type:'income',amount:480000+i*7000,date:mon+'-02',accountId:a,categoryId:category('Salário'),notes:'Dado fictício',extra:{}});for(const [j,d,amt,cat] of [[0,'Aluguel',130000,'Outros'],[1,'Mercado',32680,'Alimentação'],[2,'Internet',9900,'Assinaturas'],[3,'Transporte',17500,'Transporte']])s.transactions.push({id:uid(),description:d,type:'expense',amount:amt+i*1500,date:dateAt(mon,3+j*2),accountId:a,categoryId:category(cat),notes:'Dado fictício',extra:{}})}s.transactions.push({id:uid(),description:'Reserva do mês',type:'transfer',amount:80000,date:m+'-07',accountId:a,toAccountId:b,categoryId:'',notes:'Dado fictício',extra:{}});const card=uid();s.cards=[{id:card,name:'Cartão de exemplo',limit:600000,closing:18,due:25,color:'#243b57'}];s.purchases=[{id:uid(),cardId:card,description:'Cadeira de trabalho',amount:120000,count:4,date:addMonth(m,-1)+'-05',firstMonth:m,categoryId:category('Compras pessoais')},{id:uid(),cardId:card,description:'Livros',amount:18990,count:1,date:m+'-04',firstMonth:m,categoryId:category('Outros')}];s.recurring=[{id:uid(),name:'Internet',amount:9900,day:20,accountId:a,categoryId:category('Assinaturas')},{id:uid(),name:'Academia',amount:12990,day:15,accountId:a,categoryId:category('Outros')},{id:uid(),name:'Assinatura de música',amount:2190,day:25,accountId:a,categoryId:category('Assinaturas')}];s.goals=[{id:uid(),name:'Próxima viagem',target:500000,saved:215000,project:'Experiências',priority:'Média',impact:4,status:'planned',description:'Uma pausa para conhecer novos lugares.',url:'',dueDate:''},{id:uid(),name:'Novo monitor',target:180000,saved:90000,project:'Trabalho',priority:'Alta',impact:5,status:'planned',description:'Mais espaço para as ideias.',url:'',dueDate:''}];s.salary={hours:160,minutes:30,rate:3000,first:'Destino 1',second:'Destino 2',percent:60};return s}
